#!/bin/bash
# FILENAME: 5_mmc_annot.sh
# DESCRIPTION: OPTIONAL (written only with --mmc_reference): MapMyCells on {CELLPOSE_PREFIX} and {PROSEG_PREFIX}, labels synced into the zarr tables.
# Generated by slurm_scripts/script.py (Anvil). Step bodies follow aws_templates/aws_s3_template/.

#SBATCH -A mcb130189
#SBATCH -p shared
#SBATCH -t {T_MMC}
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=8
#SBATCH --mem=32gb
#SBATCH -J mmc_{EXP_N}_{REG_N}
#SBATCH -o {LOG_DIR}/5_mmc_annot_{EXP_N}_{REG_N}.out
#SBATCH -e {LOG_DIR}/5_mmc_annot_{EXP_N}_{REG_N}.out

module purge
module load modtree/cpu
module list

# Fail fast from here on: any non-zero exit aborts the job, so --dependency=afterok in chain.sh stops
# downstream steps. Module loads above stay non-fatal (not every module exists on every node type).
set -eo pipefail  # no -u: Lmod module functions read unset variables

export PATH="/home/x-aklein2/.pixi/bin:$PATH"
export SLURM_TMPDIR="${{SLURM_TMPDIR:-${{TMPDIR:-/tmp}}}}"
export PIXI_HOME="${{SLURM_TMPDIR}}/pixi_home_${{SLURM_JOB_ID:-$$}}"
export PIXI_CACHE_DIR="/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache"
export RATTLER_CACHE_DIR="/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache"
mkdir -p "$PIXI_HOME" "$PIXI_CACHE_DIR" "$RATTLER_CACHE_DIR"

# Run from a copy of SPIDA: edits to the source tree cannot reach a running job.
WORKDIR="${{SLURM_TMPDIR}}/spida_${{SLURM_JOB_ID:-$$}}"
rsync -a --delete --exclude '.pixi/envs' "{SPIDA_ROOT}/" "$WORKDIR/"
cd "$WORKDIR"
pixi install --frozen -e mmc

# --- Compute ---
for PREFIX in {CELLPOSE_PREFIX} {PROSEG_PREFIX}; do
    echo -e "\nMapMyCells {MMC_REFERENCE} - ${{PREFIX}} - {REG_N} - {EXP_N}\n"
    pixi run --frozen -e mmc \
        python -m spida.I --config {CONFIG_PATH} \
        mmc-annotation-region \
        ${{PREFIX}} \
        {MMC_REFERENCE} \
        --exp {EXPERIMENT} \
        --reg {REGION} \
        --suffix _filt \
        --mmc_store_path {MMC_STORE_PATH} \
        --plot \
        {MMC_ARGS}

    echo -e "\nCopying {MMC_REFERENCE} labels into the zarr table - ${{PREFIX}}\n"
    pixi run --frozen -e mmc \
        python -m spida.I --config {CONFIG_PATH} \
        sync-annotations \
        ${{PREFIX}} \
        --exp {EXPERIMENT} \
        --reg {REGION} \
        --reference {MMC_REFERENCE} \
        {OVERWRITE_ARG}
done
